{
  "rationale": "Collect segment financial performance, market share data, and qualitative disclosures for AWS, Azure (Intelligent Cloud), and Google Cloud using financial statements, SEC filings, earnings transcripts, peer comparison, and web search, then run calculation engine steps for relative metrics.",
  "steps": [
    {
      "id": "s1",
      "goal": "Retrieve SEC filing annual/quarterly disclosures for Amazon segment performance (AWS)",
      "tool": "sec_filing_search",
      "args": {
        "ticker": "AMZN",
        "filing_type": "10-K"
      },
      "depends_on": [],
      "reason": "Official segment breakdowns for revenue and operating income of AWS."
    },
    {
      "id": "s2",
      "goal": "Retrieve SEC filing disclosures for Microsoft segment performance (Intelligent Cloud / Azure)",
      "tool": "sec_filing_search",
      "args": {
        "ticker": "MSFT",
        "filing_type": "10-K"
      },
      "depends_on": [],
      "reason": "Official disclosures on Intelligent Cloud segment revenue and operating margins."
    },
    {
      "id": "s3",
      "goal": "Retrieve SEC filing disclosures for Alphabet segment performance (Google Cloud)",
      "tool": "sec_filing_search",
      "args": {
        "ticker": "GOOGL",
        "filing_type": "10-K"
      },
      "depends_on": [],
      "reason": "Official segment revenue and operating income for Google Cloud."
    },
    {
      "id": "s4",
      "goal": "Get latest earnings transcript commentary for AMZN AWS performance and margins",
      "tool": "earnings_transcript",
      "args": {
        "ticker": "AMZN"
      },
      "depends_on": [],
      "reason": "Management commentary on AWS growth drivers, AI expansion, and margin dynamics."
    },
    {
      "id": "s5",
      "goal": "Get latest earnings transcript commentary for MSFT Azure and Intelligent Cloud growth",
      "tool": "earnings_transcript",
      "args": {
        "ticker": "MSFT"
      },
      "depends_on": [],
      "reason": "Management commentary on Azure revenue growth rates, capacity constraints, and AI revenue contributions."
    },
    {
      "id": "s6",
      "goal": "Get latest earnings transcript commentary for GOOGL Google Cloud momentum",
      "tool": "earnings_transcript",
      "args": {
        "ticker": "GOOGL"
      },
      "depends_on": [],
      "reason": "Management commentary on Google Cloud profitability acceleration and GCP adoption."
    },
    {
      "id": "s7",
      "goal": "Compare key peer metrics across AMZN, MSFT, and GOOGL",
      "tool": "peer_comparison",
      "args": {
        "ticker": "AMZN",
        "peers": ["MSFT", "GOOGL"],
        "metrics": ["revenue", "revenue_growth", "operating_margin", "market_cap"]
      },
      "depends_on": [],
      "reason": "Benchmark consolidated firm metrics and valuation metrics among the Big 3 cloud providers."
    },
    {
      "id": "s8",
      "goal": "Search for cloud market share market data and independent estimates for AWS, Azure, GCP",
      "tool": "web_search",
      "args": {
        "query": "cloud infrastructure market share AWS Azure Google Cloud 2026 2025"
      },
      "depends_on": [],
      "reason": "Market share statistics for hyperscalers are published by industry analysts (Synergy, Canalys, Gartner) rather than filed directly."
    },
    {
      "id": "s9",
      "goal": "Calculate segment margins and relative growth rates once segment revenue and operating income figures are gathered",
      "tool": "calculation_engine",
      "args": null,
      "depends_on": ["s1", "s2", "s3", "s4", "s5", "s6"],
      "reason": "Compute accurate segment operating margins and YoY growth rates without manual arithmetic."
    }
  ]
}
